  L[36] = {
    minutes: 18,
    links: [{ href: '#partie', label: 'Jouer un heads-up' }, { href: '#situations', label: 'S’entraîner : tapis ou fold en heads-up' }],
    key: ['À deux, presque toutes les mains ont de la valeur : le bouton joue 75 à 85 % de ses mains, la grosse blinde en défend 60 à 70 %.', 'Une top paire, même faible, est une grosse main ; celui qui mise souvent ramasse les pots que l’autre rate deux fois sur trois.', 'Sous 15 BB : tapis ou fold avec les tables petite blinde contre grosse blinde.'],
    sections: [
      { ask: 'Qu’est-ce qui change quand on n’est plus que deux ?', h: 'Ce qui change à deux', p: ['Il n’y a plus de pression ICM : il ne reste qu’un écart de prix, entre la 1re et la 2e place, et chaque jeton gagné te rapproche de la victoire. Les décisions se prennent en jetons, comme en début de tournoi.', 'Les blindes tombent à chaque coup : tu es petite blinde un coup sur deux, grosse blinde l’autre. Attendre une grosse main coûte très cher.', 'Le bouton est aussi la petite blinde. Il parle en premier avant le flop, et en dernier après le flop : c’est un gros avantage, qu’on exploite en jouant beaucoup de mains au bouton.'] },
      { ask: 'Pourquoi jouer autant de mains ?', h: 'Presque toutes les mains ont de la valeur', p: ['Contre une main au hasard, la pire main du jeu, 3-2 dépareillé, gagne encore 32 %. 7-2 dépareillé : 35 %. Dame-5 dépareillé : 50 %. Roi-7 dépareillé : 55 %. As-2 dépareillé : 55 %.', 'À deux, il n’y a pas de « mauvaise main » au sens où on l’entend à neuf : il y a des mains un peu meilleures que la moyenne, et des mains un peu moins bonnes. Les as et les rois avec n’importe quelle carte sont déjà au-dessus de la moyenne.', 'Au flop, une main au hasard touche au moins une paire avec ses cartes environ une fois sur trois (36 %). Deux fois sur trois, l’adversaire n’a rien : celui qui mise souvent ramasse beaucoup de pots.'] },
      { ask: 'Que faire au bouton selon mon tapis ?', h: 'Le bouton (petite blinde) selon le tapis', p: ['Au-dessus de 25 BB : joue 75 à 85 % de tes mains. Relance au minimum (2 BB) avec la plupart. Certains joueurs limpent aussi des mains faibles mais jouables (petites mains assorties, mains dépareillées moyennes) pour voir des flops pas chers ; c’est une option, pas une obligation.', 'Pourquoi une relance minimum ? Tu risques 1,5 BB de plus pour gagner les blindes. Si l’adversaire se couche plus d’une fois sur trois environ, la relance gagne déjà, même sans compter ce que tu gagnes quand il paie.', 'De 15 à 25 BB : relance moins de mains, et décide avant de relancer ce que tu feras s’il fait tapis. Une main qui ne paierait pas son tapis peut parfois pousser directement à la place.', 'Sous 15 BB : tapis ou fold, avec les tables. Le bouton pousse 65 % des mains à 15 BB, 74 % à 10 BB, 83 % à 5 BB. Roi-7 et dame-5 dépareillés poussent à 10 BB.'] },
      { ask: 'Et en grosse blinde ?', h: 'La grosse blinde', p: ['Face à une relance minimum, il te faut environ 25 % d’équité pour payer, et presque toutes les mains l’ont contre une range de bouton large. Défends 60 à 70 % de tes mains : paie la plupart, et sur-relance (3-bet) tes meilleures mains et quelques mains bloquantes (as faibles, rois assortis).', 'Si le bouton limpe, relance souvent : il a montré une main moyenne. Relance à 3 ou 4 BB avec tes bonnes mains et une partie de tes mains moyennes ; checke le reste et regarde le flop gratuitement.', 'Face au tapis du bouton sous 15 BB, paie avec 41 % des mains à 15 BB, 56 % à 10 BB, 86 % à 5 BB. À 10 BB, roi-2 dépareillé paie ; valet-6 dépareillé se couche.'] },
      { ask: 'Comment jouer après le flop à deux ?', h: 'Après le flop : l’agressivité paie', p: ['Une top paire, même avec un petit kicker, est une grosse main à deux : K-3 sur K♥ 7♠ 2♦ gagne 83 % contre une main au hasard. Mise pour la valeur sur deux ou trois rues.', 'Une paire moyenne garde de la valeur : 7-7 sur K♥ 9♠ 2♦ gagne encore 62 % contre une main au hasard. As hauteur sur ce flop : 47 %. Ces mains aiment checker et payer, pas se coucher à la première mise.', 'Sans rien, mise souvent au flop quand tu as relancé avant : l’adversaire rate deux fois sur trois. Mais choisis tes deuxièmes mises (turn) : avec des tirages, des cartes hautes qui t’aident, ou contre un joueur qui se couche beaucoup.', 'En défense, ne te couche pas par réflexe : les ranges sont larges, une paire faible ou un as hauteur gagnent souvent. Relance parfois au flop (check-raise) avec tes paires et tes tirages : à deux, c’est l’arme qui punit les mises trop fréquentes.'] },
      { ask: 'Et contre un adversaire précis ?', h: 'S’adapter à l’adversaire', p: ['Le passif qui attend sa main : vole sans arrêt avant le flop, mise souvent au flop, et quand il paie ou relance, crois-le. Mise gros pour la valeur, il paie avec ses paires.', 'L’agressif qui relance tout : paie plus large, laisse-le bluffer, piège avec tes paires (check, puis paie ou relance tard). Sur-relance plus souvent avant le flop pour la valeur.', 'Le joueur qui se couche trop face au tapis : pousse plus large que les tables. Celui qui paie tout : pousse plus serré, mais avec des mains qui dominent les siennes (as, rois).', 'Regarde ce qu’il montre à l’abattage : à deux, chaque main montrée en dit beaucoup sur sa range.'] },
      { ask: 'Faut-il faire un deal ?', h: 'Le deal et le mental', p: ['À deux, on peut se partager les gains selon les tapis (deal). Un deal réduit la variance. Si tu penses être meilleur que ton adversaire en heads-up, continuer rapporte plus en moyenne ; si tu es fatigué ou plus faible, le deal protège ton résultat.', 'Le heads-up est rapide et intense : chaque coup compte, les écarts de tapis bougent vite. Garde la même discipline qu’en début de tournoi : un mauvais coup ne doit pas décider des cinq suivants.', 'Pour t’entraîner : S’entraîner › Jouer une partie, format Heads-up (25, 40 ou 100 BB), et l’exercice « Tapis ou fold en heads-up ».'] }
    ],
    mistake: 'Jouer le heads-up comme une table à neuf : attendre une grosse main pendant que les blindes, à chaque coup, mangent le tapis.',
    retain: ['Bouton : 75 à 85 % des mains au-dessus de 25 BB, relance minimum.', 'Grosse blinde : défends 60 à 70 %, relance les limps.', 'Sous 15 BB, tables : bouton 74 % et grosse blinde 56 % à 10 BB.', 'Top paire = grosse main ; paire moyenne et as hauteur : checker et payer.', 'Adapte-toi : vole le passif, laisse bluffer l’agressif.'],
    quiz: [
      { q: 'En heads-up, le bouton est aussi…', o: ['la grosse blinde', 'la petite blinde', 'le premier à parler après le flop', 'hors du coup'], a: 1, why: 'Il paie la petite blinde, parle en premier avant le flop et en dernier après.' },
      { q: 'Contre une main au hasard, 7-2 dépareillé gagne environ…', o: ['5 %', '15 %', '35 %', '50 %'], a: 2, why: 'Environ 35 % : même la pire main garde de l’équité à deux.' },
      { q: 'Au bouton avec 40 BB, quelle part de tes mains joues-tu environ ?', o: ['20 %', '40 %', '75 à 85 %', '100 %'], a: 2, why: 'À deux, presque toutes les mains ont assez d’équité et la position aide.' },
      { q: 'Ta relance minimum au bouton est rentable dès que l’adversaire se couche environ…', o: ['une fois sur dix', 'un peu plus d’une fois sur trois', 'deux fois sur trois', 'jamais'], a: 1, why: 'Tu risques 1,5 BB pour gagner 2,5 BB (les blindes et l’ante) : environ 37 % d’abandons suffisent, sans compter tes gains quand il paie.' },
      { q: 'Heads-up à 10 BB, en grosse blinde avec roi-2 dépareillé face au tapis :', o: ['tu te couches', 'tu paies', 'tu relances', 'ça dépend du flop'], a: 1, why: 'La grosse blinde paie 56 % des mains à 10 BB, roi-2 est dedans.' },
      { q: 'K♥ 7♠ 2♦ à deux, tu as K♣3♦. Ta main est…', o: ['faible, check-fold', 'moyenne', 'forte : mise pour la valeur', 'à jouer seulement en bluff'], a: 2, why: 'Elle gagne 83 % contre une main au hasard.' },
      { q: 'Ton adversaire relance presque tous ses boutons. Tu…', o: ['te couches plus', 'paies et sur-relances plus large', 'limpes', 'ne changes rien'], a: 1, why: 'Contre une range très large, tes mains moyennes deviennent fortes.' },
      { q: 'Sous 15 BB en heads-up, on joue…', o: ['des petites relances', 'tapis ou fold avec les tables', 'uniquement les paires', 'en limpant'], a: 1, why: 'Les tables petite blinde contre grosse blinde s’appliquent telles quelles en heads-up.' }
    ]
  };

  L[36].podcast = [
    ['J', 'Salut Yo ! Aujourd’hui, le heads-up. Il ne reste que nous deux à la table finale.'],
    ['Y', 'Salut ! Le moment le plus important du tournoi. C’est là que se joue le plus gros écart de gains. Et c’est là que les joueurs serrés laissent le plus d’argent.'],
    ['J', 'Pourquoi ?'],
    ['Y', 'Parce qu’ils jouent comme à neuf. Ils attendent une grosse main. Mais à deux, tu paies une blinde à chaque coup. Attendre coûte très cher.'],
    ['J', 'Qu’est-ce qui change d’autre ?'],
    ['Y', 'Le bouton est aussi la petite blinde. Il parle en premier avant le flop, et en dernier après le flop. Et il n’y a plus de pression ICM : chaque jeton gagné te rapproche de la victoire.'],
    ['J', 'Alors, combien de mains je joue au bouton ?'],
    ['Y', 'Avec plus de vingt-cinq blindes, entre trois quarts et presque toutes. Soixante-quinze à quatre-vingt-cinq pour cent.'],
    ['J', 'Même sept-deux ?'],
    ['Y', 'Sept-deux, c’est la limite. Mais regarde : contre une main au hasard, sept-deux gagne trente-cinq pour cent. La pire main du jeu, trois-deux, trente-deux pour cent. Dame-cinq, cinquante. Roi-sept, cinquante-cinq.'],
    ['J', 'Donc à deux, il n’y a presque pas de mauvaise main.'],
    ['Y', 'Voilà. Il y a des mains un peu meilleures que la moyenne, et des mains un peu moins bonnes. Les as et les rois avec n’importe quoi sont déjà au-dessus.'],
    ['J', 'Et je relance combien ?'],
    ['Y', 'Le minimum, deux blindes. Tu risques une blinde et demie pour gagner les blindes. Si l’adversaire se couche un peu plus d’une fois sur trois, c’est déjà rentable, sans même compter les coups que tu gagnes quand il paie.'],
    ['J', 'Et en grosse blinde ?'],
    ['Y', 'Face à une relance minimum, il te faut environ un quart d’équité pour payer. Presque toutes tes mains l’ont. Défends soixante à soixante-dix pour cent : paie la plupart, et sur-relance tes meilleures mains.'],
    ['J', 'Et s’il limpe ?'],
    ['Y', 'Relance souvent. Un limp, c’est une main moyenne. Relance à trois ou quatre blindes avec tes bonnes mains et une partie des moyennes, et checke le reste.'],
    ['J', 'Et quand les tapis sont courts ?'],
    ['Y', 'Sous quinze blindes, tapis ou fold. Le bouton pousse soixante-cinq pour cent des mains à quinze blindes, trois mains sur quatre à dix blindes, et presque tout à cinq. Roi-sept, dame-cinq dépareillés : tapis à dix blindes.'],
    ['J', 'Et la grosse blinde paie avec quoi ?'],
    ['Y', 'À dix blindes, un peu plus de la moitié des mains. Roi-deux paie. Valet-six se couche. À cinq blindes, presque tout paie.'],
    ['J', 'Passons au flop.'],
    ['Y', 'Au flop, une main au hasard touche au moins une paire une fois sur trois. Deux fois sur trois, ton adversaire n’a rien. Alors celui qui mise souvent ramasse beaucoup de pots.'],
    ['J', 'Et une top paire avec un petit kicker ?'],
    ['Y', 'C’est une grosse main à deux. Roi-trois sur roi, sept, deux : quatre-vingt-trois pour cent contre une main au hasard. Mise pour la valeur, deux ou trois fois.'],
    ['J', 'Et une paire moyenne ?'],
    ['Y', 'Sept-sept sur roi, neuf, deux : encore soixante-deux pour cent. As hauteur sur ce flop : quarante-sept. Ces mains-là aiment checker et payer. Ne les jette pas à la première mise.'],
    ['J', 'Et quand je n’ai rien ?'],
    ['Y', 'Mise souvent au flop si tu as relancé avant. Mais choisis bien ta deuxième mise : avec un tirage, avec une carte haute qui t’aide, ou contre quelqu’un qui se couche trop.'],
    ['J', 'Et en défense ?'],
    ['Y', 'Ne te couche pas par réflexe. Et relance parfois au flop avec tes paires et tes tirages. À deux, le check-raise punit ceux qui misent tout le temps.'],
    ['J', 'Et selon l’adversaire ?'],
    ['Y', 'Contre le passif qui attend sa main : vole sans arrêt, et crois-le quand il relance. Contre l’agressif : paie plus large, laisse-le bluffer, et piège avec tes paires.'],
    ['J', 'Et le deal ?'],
    ['Y', 'Si tu penses être meilleur que lui en heads-up, continue. Si tu es fatigué ou moins fort, le deal protège ton résultat. C’est ton choix, il n’y a pas de honte.'],
    ['J', 'Et pour m’entraîner ?'],
    ['Y', 'Dans l’appli, Jouer une partie, format heads-up, avec vingt-cinq, quarante ou cent blindes. Et l’exercice tapis ou fold en heads-up.'],
    ['J', 'Le quiz ?'],
    ['Y', 'Première question. Contre une main au hasard, sept-deux gagne environ combien ?'],
    ['P', 5],
    ['J', 'Trente-cinq pour cent.'],
    ['Y', 'Oui.'],
    ['Y', 'Deuxième question. Roi, sept, deux. Tu as roi-trois. Ta main est forte ou faible ?'],
    ['P', 5],
    ['J', 'Forte : je mise pour la valeur.'],
    ['Y', 'Bravo.'],
    ['Y', 'Troisième question. Dix blindes, grosse blinde, roi-deux dépareillé face au tapis.'],
    ['P', 5],
    ['J', 'Je paie.'],
    ['Y', 'Parfait. On résume. À deux, presque toutes les mains ont de la valeur : joue trois quarts de tes mains au bouton, défends deux tiers en grosse blinde. Relance au minimum. Sous quinze blindes, tapis ou fold avec les tables. Une top paire, même faible, est une grosse main. Mise souvent : ton adversaire rate deux fois sur trois. Et adapte-toi à lui. Bon heads-up !']
  ];

  L[37] = {
    minutes: 14,
    links: [{ href: '#ranges', label: 'Ma range › Vue globale' }, { href: '#ranges', label: 'Ma range › Face à un 3-bet › J’ouvre en SB' }, { href: '#solveur', label: 'Le solveur : petite blinde contre grosse blinde' }],
    key: ['Voler les blindes, c’est ouvrir pour ramasser les blindes et les antes sans combat. Plus tu es près du bouton, moins il reste de joueurs pour te réveiller : c’est là qu’on vole.', 'Avec une ouverture à 2 BB et une ante de grosse blinde, le vol est rentable dès que tout le monde se couche 44 % du temps, sans même compter les coups gagnés après le flop.'],
    sections: [
      { ask: 'Qu’est-ce que voler les blindes ?', h: 'Le principe', p: ['Quand tout le monde s’est couché jusqu’à toi en fin de table (hijack, cut-off, bouton, petite blinde), tu ouvres une range plus large que ta « valeur » pure : ton but est souvent de ramasser les blindes et l’ante, pas de jouer un gros pot.', 'Avant que tu ouvres, il y a déjà 2,5 BB au milieu avec l’ante de grosse blinde (petite blinde 0,5 + grosse blinde 1 + ante 1). Tu risques 2 BB pour les gagner.'] },
      { ask: 'Quand est-ce rentable ?', h: 'Le calcul du vol', p: ['Tu mises 2 BB pour gagner 2,5 BB : le vol est rentable dès que tout le monde se couche plus de 44 % du temps (2 ÷ (2 + 2,5)). Et c’est un minimum : quand on te paie, tu gagnes encore une partie de ces coups après le flop.', 'Contre des joueurs qui défendent comme le profil TAG, tout le monde se couche environ 47 % du temps derrière une ouverture du hijack, 51 % derrière le cut-off, 44 % derrière le bouton (les blindes défendent beaucoup contre lui) et 67 % derrière la petite blinde. Contre des joueurs serrés, c’est 56 à 72 % : le vol rapporte encore plus.'] },
      { ask: 'Combien de mains j’ouvre pour voler ?', h: 'Les ranges de vol par position', p: ['À 40 BB et plus, profil TAG : hijack 22 %, cut-off 29 %, bouton 47 %, petite blinde 32 %. Profil serré : 18, 21, 30 et 22 %. Profil large-agressif : 30, 41, 56 et 43 %.', 'Entre 20 et 40 BB, on resserre un peu (TAG : hijack 17 %, cut-off 25 %, petite blinde 27 %) : un 3-bet adverse met vite ton tapis en jeu. Sous 20 BB, le vol se fait à tapis, avec les tables du chapitre 22.', 'Tu retrouves ces ranges dans Ma range › Vue globale : survole ou touche une main pour voir à partir d’où on l’ouvre, et quoi faire si on te relance.'] },
      { ask: 'Et depuis la petite blinde ?', h: 'Le vol depuis la petite blinde', p: ['Il ne reste que la grosse blinde. Tu as déjà mis 0,5 BB : en ouvrant à 3 BB, tu risques 2,5 BB de plus pour gagner 2,5 BB. Il faut que la grosse blinde se couche une fois sur deux ; un joueur TAG en grosse blinde ne défend qu’un tiers de ses mains face à toi.', 'Le défaut : tu joueras hors de position après le flop. Le solveur (petite blinde contre grosse blinde) checke donc plus d’une fois sur deux au flop, même sur un flop roi sec, et ne mise souvent qu’un tiers du pot.', 'Au club, beaucoup de grosses blindes défendent trop, par principe. Contre elles, vole avec des mains qui jouent bien après le flop (as, rois, mains assorties) plutôt qu’avec les pires mains.'] },
      { ask: 'Et le hijack, c’est encore du vol ?', h: 'Le hijack et le cut-off', p: ['Au cut-off, il reste trois joueurs : le bouton, qui joue en position contre toi, et les deux blindes. C’est la vraie position de vol avec le bouton : 29 % des mains en TAG.', 'Au hijack, il en reste quatre : le vol marche encore (47 % d’abandons contre des TAG), mais un joueur de plus peut te réveiller. On vole moins large : 22 %, surtout des mains qui jouent bien si on te paie (as assortis, connecteurs assortis, figures).', 'Plus il reste de joueurs derrière, plus ta range doit rester solide : un vol du hijack avec une main faible qui se fait 3-bet est un pli perdu à chaque fois.'] },
      { ask: 'Et si on me relance ?', h: 'Face au 3-bet de vol (re-steal)', p: ['Les bons joueurs en blinde savent que tu voles : ils sur-relancent plus large contre le cut-off et le bouton. Prépare ta réponse avant d’ouvrir : c’est exactement ce que montre le Plan de jeu (Ma range) pour chaque main.', 'À 40 BB, un 4-bet met tout ton tapis : tu continues avec tes mains fortes et quelques mains bloquantes, tu te couches avec le reste sans regret. Ton vol a déjà rapporté sur toutes les fois où tout le monde s’est couché.'] },
      { ask: 'Et si la grosse blinde me 3-bet quand j’ouvre de la petite blinde ?', h: 'Blinde contre blinde : face au 3-bet de la grosse blinde', p: ['C’est un cas à part. Quand tu ouvres de la petite blinde, la grosse blinde sait que ta range est large (32 % en TAG) : elle sur-relance donc bien plus souvent qu’elle ne le ferait contre un joueur de début de table, souvent à 3 fois ton ouverture (environ 9 BB). Elle a aussi l’avantage de la position pour tout le reste du coup.', 'Deux idées guident ta réponse. Un : sa range de 3-bet est large, donc tu peux continuer avec plus de mains qu’au cut-off face au bouton. Deux : tu joues hors de position, donc tu paies surtout les mains qui jouent bien après le flop (paires moyennes, as et rois assortis, connecteurs assortis) et tu 4-bets les mains qui n’aiment pas jouer un flop hors de position.', 'En TAG à 100 BB : 4-bet avec QQ et plus, AK, et A5s-A4s pour le bluff (l’as bloque ses grosses mains). Paie avec JJ à 66, AQs à ATs, KQs, KJs, QJs, JTs, T9s, 98s, AQo, AJo et KQo. Couche le reste de ton ouverture : K9o, Q8s, les petites cartes dépareillées.', 'Profil serré : 4-bet QQ+ et AK, paie JJ-99, AQs, AJs, KQs et AQo. Profil large-agressif : 4-bet aussi JJ, AQs, quelques rois et dames assortis en bluff ; paie de TT à 44 et beaucoup d’assorties. Tout est dans Ma range › Face à un 3-bet › « J’ouvre en SB, 3-bet de la BB ».', 'Exemple : tu ouvres A9s en petite blinde, la grosse blinde sur-relance à 9 BB. Tu paies : la main fait des couleurs max et des paires d’as. Avec K9o, couche-toi : dépareillée et dominée, elle perd beaucoup d’argent hors de position. Avec A5s, 4-bet à environ 20 BB : si elle fait tapis, couche-toi sans regret.'] },
      { ask: 'Quand voler plus, quand voler moins ?', h: 'Adapter le vol', p: ['Vole plus : contre des blindes serrées (nit, survivant), à la bulle contre les tapis moyens qui ont peur, quand les blindes sont courtes et jouent tapis ou fold avec des ranges serrées.', 'Vole moins : contre une calling station en grosse blinde (elle paie tout : ouvre plutôt pour la valeur et mise gros après le flop), contre un joueur qui 3-bet très souvent, et quand tu as une image de voleur après plusieurs ouvertures de suite.'] }
    ],
    mistake: 'Voler avec n’importe quelles deux cartes depuis le hijack, ou continuer à voler une calling station qui paie toutes ses grosses blindes.',
    retain: ['Petite blinde face au 3-bet de la grosse blinde : défends plus large qu’au cut-off, mais paie surtout les mains assorties et les paires ; 4-bet QQ+, AK et A5s-A4s en TAG.', 'Vol rentable si tout le monde se couche plus de 44 % du temps (ouverture 2 BB, ante BB).', 'Ranges TAG : HJ 22 %, CO 29 %, BTN 47 %, SB 32 %.', 'Petite blinde : ouvre 3 BB, checke souvent au flop hors de position.', 'Prépare ta réponse au 3-bet avant d’ouvrir (Plan de jeu).', 'Vole plus contre les serrés et à la bulle, moins contre les stations et les 3-betteurs.'],
    quiz: [
      { q: 'Avec une ouverture à 2 BB et une ante de grosse blinde, le vol est rentable dès que tout le monde se couche environ…', o: ['20 % du temps', '44 % du temps', '70 % du temps', '90 % du temps'], a: 1, why: '2 ÷ (2 + 2,5) = 44 %, sans compter tes gains quand on te paie.' },
      { q: 'Profil TAG à 40 BB : quelle part de mains ouvres-tu au cut-off ?', o: ['10 %', '29 %', '47 %', '70 %'], a: 1, why: 'Hijack 22 %, cut-off 29 %, bouton 47 %, petite blinde 32 %.' },
      { q: 'Depuis la petite blinde, ton vol est rentable si la grosse blinde se couche…', o: ['une fois sur quatre', 'une fois sur deux', 'neuf fois sur dix', 'jamais'], a: 1, why: 'Tu risques 2,5 BB de plus pour gagner 2,5 BB.' },
      { q: 'Contre une calling station en grosse blinde, tu…', o: ['voles encore plus large', 'voles moins et mises gros pour la valeur', 'ne joues plus jamais', 'limpes tout'], a: 1, why: 'Elle ne se couche pas : le vol perd sa raison d’être.' },
      { q: 'Tu ouvres en petite blinde, la grosse blinde te 3-bet à 9 BB. Tu as KJs (100 BB, TAG). Que fais-tu ?', o: ['Je me couche', 'Je paie', 'Je 4-bet tapis', 'Je 4-bet puis je me couche'], a: 1, why: 'Sa range de 3-bet est large contre la petite blinde : KJs joue bien après le flop, tu paies.' },
      { q: 'Même situation avec K9o. Que fais-tu ?', o: ['Je me couche', 'Je paie', 'Je 4-bet', 'Je fais tapis'], a: 0, why: 'Dépareillée et souvent dominée, elle perd de l’argent hors de position : couche-toi.' },
      { q: 'Pourquoi 4-bet A5s plutôt que la payer, face au 3-bet de la grosse blinde ?', o: ['Parce que c’est une main premium', 'Parce que l’as bloque ses grosses mains et qu’on se couche sans regret si elle fait tapis', 'Pour gagner plus quand elle paie', 'Parce qu’on ne peut pas payer en petite blinde'], a: 1, why: 'C’est un bluff qui bloque AA et AK, avec de l’équité si elle paie.' },
      { q: 'Pourquoi voler moins large au hijack qu’au bouton ?', o: ['Parce que les blindes sont plus grosses', 'Parce qu’il reste plus de joueurs pour te relancer', 'Parce qu’on ne peut pas', 'Ce n’est pas vrai'], a: 1, why: 'Quatre joueurs derrière au hijack, deux au bouton.' }
    ]
  };

  L[37].podcast = [
    ['J', 'Salut Yo ! Aujourd’hui, voler les blindes. On en parle souvent au club, mais je ne sais pas si je le fais bien.'],
    ['Y', 'Salut ! Le vol, c’est simple : tout le monde se couche jusqu’à toi, en fin de table, et tu ouvres pour ramasser les blindes et l’ante. Pas pour jouer un gros coup.'],
    ['J', 'Et c’est rentable ?'],
    ['Y', 'Fais le compte. Avec l’ante de grosse blinde, il y a déjà deux blindes et demie au milieu. Tu ouvres à deux. Tu risques deux pour en gagner deux et demie.'],
    ['J', 'Donc il faut qu’ils se couchent souvent.'],
    ['Y', 'Plus de quarante-quatre pour cent du temps. Et c’est un minimum, parce que quand on te paie, tu gagnes encore une partie des coups après le flop.'],
    ['J', 'Et en vrai, ils se couchent combien ?'],
    ['Y', 'Contre des joueurs réguliers, environ une fois sur deux derrière le cut-off. Deux fois sur trois derrière la petite blinde. Et contre des joueurs serrés, jusqu’à sept fois sur dix.'],
    ['J', 'Combien de mains j’ouvre ?'],
    ['Y', 'Avec ton profil, à quarante blindes : hijack vingt-deux pour cent, cut-off vingt-neuf, bouton quarante-sept, petite blinde trente-deux.'],
    ['J', 'Et depuis la petite blinde, c’est spécial ?'],
    ['Y', 'Oui. Il ne reste que la grosse blinde. Tu ouvres à trois blindes : il faut qu’elle se couche une fois sur deux. Mais tu joueras hors de position. Alors après le flop, le solveur checke plus d’une fois sur deux, même sur un flop roi sec.'],
    ['J', 'Et le hijack ?'],
    ['Y', 'Encore du vol, mais plus prudent. Il reste quatre joueurs. On vole avec des mains qui jouent bien si on te paie : as assortis, connecteurs assortis, figures.'],
    ['J', 'Et si la grosse blinde me relance ?'],
    ['Y', 'Prépare ta réponse avant d’ouvrir. Le plan de jeu de Ma range te le dit main par main. À quarante blindes, un quatre-bet, c’est ton tapis : tu continues avec tes mains fortes, tu jettes le reste sans regret.'],
    ['J', 'Et si j’ouvre de la petite blinde, et que la grosse blinde me sur-relance ?'],
    ['Y', 'C’est un cas à part. Elle sait que tu ouvres large de la petite blinde, alors elle sur-relance souvent, autour de neuf blindes. Et elle aura la position sur toi pour tout le coup.'],
    ['J', 'Je me couche, alors ?'],
    ['Y', 'Pas si vite. Sa range est large : tu continues avec plus de mains qu’au cut-off face au bouton. Mais tu joues hors de position, alors tu paies les mains qui jouent bien après le flop : les paires moyennes, les as et les rois assortis, les connecteurs assortis.'],
    ['J', 'Et le quatre-bet ?'],
    ['Y', 'Avec dame-dame et plus, et as-roi. En bluff, as-cinq et as-quatre assortis : l’as bloque ses grosses mains. Roi-neuf dépareillé, par contre, tu le jettes : souvent dominé, il joue mal hors de position.'],
    ['J', 'Où je retrouve ça ?'],
    ['Y', 'Dans Ma range, Face à un trois-bet, puis J’ouvre en petite blinde, trois-bet de la grosse blinde.'],
    ['J', 'Et quand je vole plus, ou moins ?'],
    ['Y', 'Plus contre les joueurs serrés, et à la bulle contre ceux qui ont peur. Moins contre une calling station en grosse blinde : elle paie tout. Contre elle, ouvre pour la valeur et mise gros après le flop.'],
    ['J', 'Le quiz ?'],
    ['Y', 'Première question. À partir de quelle fréquence d’abandons le vol est rentable ?'],
    ['P', 5],
    ['J', 'Quarante-quatre pour cent.'],
    ['Y', 'Oui.'],
    ['Y', 'Deuxième question. Depuis la petite blinde, la grosse blinde doit se coucher combien de fois ?'],
    ['P', 5],
    ['J', 'Une fois sur deux.'],
    ['Y', 'Bravo. On résume. Vole en fin de table : quarante-quatre pour cent d’abandons suffisent. Cut-off et bouton sont les vraies places de vol, le hijack plus prudemment, la petite blinde avec une ouverture à trois et beaucoup de checks après le flop. Prépare ta réponse au trois-bet, y compris en petite blinde face à la grosse blinde : paie les mains qui jouent bien hors de position, quatre-bet la valeur et as-cinq, as-quatre. Et adapte-toi : plus contre les serrés, moins contre les stations. À bientôt !']
  ];

  L[38] = {
    minutes: 20,
    links: [{ href: '#cas', label: 'S’entraîner : cas concrets' }, { href: '#apf', label: 'Après le flop : que faire ?' }],
    key: ['Chaque cas vient du solveur de l’appli, à 40 BB : ce qu’il fait avec une main précise, pourquoi, avec quelle mise, et la suite.', 'Une règle revient partout : on mise quand le flop favorise sa range, on checke ou on abandonne quand il favorise celle de l’adversaire.'],
    sections: [
      { ask: 'J’ai 3-bet avec A4 assorti en grosse blinde, le bouton a payé, je rate le flop. Je fais quoi ?', h: 'Cas 1 : A4 assorti, 3-bet en grosse blinde, flop raté', p: ['Le bouton ouvre, tu 3-bet à 8 BB en grosse blinde avec A♥4♥, il paie. Pot 17,5 BB, il te reste 32 BB, tu parles en premier.', 'K♦ 8♠ 3♣ : tu mises presque toujours, surtout la moitié du pot (73 %). Ta range de 3-bet a beaucoup de AK, KK, AA ; la sienne peu de rois forts. Tu représentes la force, et ton as bloque ses as. S’il paie, tu as encore l’as. S’il fait tapis, tu te couches.', 'Q♥ T♠ 7♠ ou J♦ T♠ 3♣ : mitigé. Tu checkes un tiers du temps, et tu mises la moitié du pot environ une fois sur trois.', '9♠ 7♦ 5♣ : tu checkes 91 %, et tu te couches s’il mise (99 %). Ce flop touche sa range de paye, pas la tienne : on abandonne.'] },
      { ask: 'Et si c’est moi qui 3-bet au bouton, en position ?', h: 'Cas 2 : A4 assorti, 3-bet au bouton, flop raté', p: ['Le cut-off ouvre, tu 3-bet au bouton avec A4 assorti, il paie et checke le flop. Pot 15,5 BB.', 'K♦ 8♠ 3♣ : tu mises 88 %, surtout la moitié du pot. Q♥ T♠ 7♠ et 9♠ 7♦ 5♣ : tu checkes environ 80 %. En position, tu prends la carte gratuite : ton as peut encore gagner, et tu verras sa réaction à la turn.', 'La règle des deux cas : on bluffe quand le flop favorise celui qui a 3-bet (cartes hautes, flop sec), on renonce quand il favorise celui qui a payé (flop bas et connecté). La taille : la moitié du pot suffit, le tapis est déjà proche.'] },
      { ask: 'J’ai relancé avec AK au bouton et je rate. Je mise toujours ?', h: 'Cas 3 : AK raté en pot simple', p: ['Tu ouvres AK dépareillé au bouton, la grosse blinde paie. 40 BB, pot 5,5 BB.', 'J♣ 5♦ 2♥ (sec, une seule carte haute) : tu mises 94 %, surtout un tiers du pot. La grosse blinde rate très souvent ce genre de flop, et AK a six outs pour une top paire.', 'K♦ 8♠ 3♣, où tu as touché la top paire : tu mises aussi, 75 %, plutôt petit.', '9♠ 7♦ 5♣ (bas et connecté) : tu checkes 52 %. Quand tu mises, toutes les tailles servent. La grosse blinde a beaucoup de paires et de tirages ici : un petit bluff ne fait pas coucher grand monde.'] },
      { ask: 'J’ai touché la top paire en grosse blinde, il mise. Je relance ou je paie ?', h: 'Cas 4 : top paire en grosse blinde', p: ['Tu défends ta grosse blinde avec K♠T♦ contre le bouton. Flop K♦ 8♠ 3♣, tu checkes, il mise.', 'Face à un tiers du pot : tu relances 62 %, tu paies 38 %. Une petite mise laisse trop de mains continuer : tu fais payer ses paires et ses as tout de suite. Avec K9 assorti, c’est presque pareil (relance 56 %).', 'Face à trois quarts du pot : tu paies 91 %. Sa grosse mise représente plus de mains fortes, et ta top paire au kicker moyen préfère contrôler la taille du pot.'] },
      { ask: 'J’ai une paire moyenne et il mise deux fois. Je tiens jusqu’où ?', h: 'Cas 5 : paire moyenne face à deux mises', p: ['Flop K♦ 8♠ 3♣ : tu paies un tiers du pot en grosse blinde avec une paire de 8 ou une paire sous le roi. Turn 2♦, il mise maintenant la taille du pot.', 'Le solveur paie 58 % avec les paires moyennes, se couche 32 %. Avec les petites paires, il se couche 67 %. Face à une grosse mise à la turn, la paire moyenne devient une décision serrée, et la petite paire se couche.', 'Au club, les deuxièmes grosses mises sont rarement des bluffs : penche du côté de l’abandon avec les petites paires.'] },
      { ask: 'J’ai un tirage couleur en pot 3-bet. Je mise ?', h: 'Cas 6 : tirage couleur en pot 3-bet', p: ['Tu as 3-bet au bouton, le cut-off a payé et checke. Flop K♥ 7♠ 2♥ avec un tirage couleur à cœur.', 'Le solveur mise 86 % de ses tirages couleur, surtout la moitié du pot. En pot 3-bet, le tapis est proche : une mise maintenant prépare le tapis à la turn, et tu as deux façons de gagner, il se couche ou ta couleur rentre.', 'En grosse blinde, après avoir 3-bet le bouton, même flop : tu mises aussi presque toujours, et part parfois directement à tapis.'] },
      { ask: 'Quand faire un check-raise en grosse blinde ?', h: 'Cas 7 : le check-raise en grosse blinde', p: ['Tu défends ta grosse blinde contre le bouton. Flop 8♥ 7♥ 4♦, tu checkes, il mise un tiers du pot.', 'Avec un tirage couleur, le solveur relance 82 % du temps, dont 27 % directement à tapis. Avec un brelan, il relance toujours. Ses paires moyennes et petites paient presque toujours, ses mains sans rien se couchent 59 %.', 'Sur un flop bas et connecté, la grosse blinde a plus de grosses mains que le bouton : c’est le meilleur moment pour relancer, avec la valeur et les gros tirages.'] },
      { ask: 'J’ai une overpaire sur un flop bas. Je mise combien ?', h: 'Cas 8 : overpaire sur un flop bas', p: ['Tu as ouvert Q♠Q♣ au bouton, la grosse blinde paie. Flop 8♥ 7♥ 4♦, elle checke.', 'Le solveur mise gros 82 % du temps : 1,25 fois le pot (57 %) ou trois quarts du pot (25 %). Ce flop donne beaucoup de tirages et de paires à la grosse blinde : une grosse mise les fait payer cher, et prépare le tapis en deux rues.', 'Sur un flop sec avec une carte haute, la même overpaire mise plutôt petit : il y a peu de tirages à faire payer.'] },
      { ask: 'J’ai volé depuis la petite blinde et la grosse blinde paie. Je mise au flop ?', h: 'Cas 9 : après un vol de la petite blinde', p: ['Tu ouvres à 3 BB en petite blinde, la grosse blinde paie. Flop K♦ 8♠ 3♣, tu parles en premier.', 'Le solveur checke 54 %, même sur ce flop sec. Quand il mise, c’est surtout un tiers du pot. Sa top paire checke presque une fois sur deux : hors de position, il garde des mains fortes dans ses checks pour ne pas être lisible.', 'Si tu mises un tiers du pot, la grosse blinde se couche 28 %, paie 54 % et relance 18 %. Hors de position, n’espère pas gagner tous les pots au flop : choisis tes mises.'] }
    ],
    mistake: 'Jouer sa main sans regarder à qui le flop profite : bluffer un flop bas et connecté contre la grosse blinde, ou checker un flop roi sec qu’on devait prendre.',
    retain: ['3-bet raté : mise sur les flops hauts et secs, abandonne sur les flops bas et connectés.', 'AK raté : mise petit sur flop sec, checke souvent sur flop bas.', 'Top paire en grosse blinde : relance une petite mise, paie une grosse.', 'Paire moyenne face à deux grosses mises : décision serrée ; petite paire : couche.', 'Overpaire sur flop bas : mise gros. Check-raise : tirages forts et brelans sur flops bas.'],
    quiz: [
      { q: 'Tu as 3-bet A4s en grosse blinde, le bouton a payé. Flop 9♠ 7♦ 5♣. Le plus souvent :', o: ['tu mises la moitié du pot', 'tu checkes et tu te couches s’il mise', 'tu fais tapis', 'tu mises le pot'], a: 1, why: 'Check 91 %, couche 99 % face à une mise : le flop favorise sa range.' },
      { q: 'Même 3-bet, flop K♦ 8♠ 3♣ :', o: ['tu checkes', 'tu mises, surtout la moitié du pot', 'tu fais tapis', 'tu te couches'], a: 1, why: 'Tu mises presque toujours : ta range a beaucoup plus de rois forts que la sienne.' },
      { q: 'AK au bouton, flop J♣ 5♦ 2♥ :', o: ['check', 'mise un tiers du pot', 'surmise', 'tapis'], a: 1, why: 'Mise 94 %, surtout un tiers du pot : flop sec que la grosse blinde rate souvent.' },
      { q: 'K♠T♦ en grosse blinde sur K♦ 8♠ 3♣, le bouton mise un tiers du pot :', o: ['tu te couches', 'tu relances le plus souvent', 'tu paies toujours', 'tu fais tapis à chaque fois'], a: 1, why: 'Relance 62 % : tu fais payer ses paires et ses as.' },
      { q: 'Même main, mais il mise trois quarts du pot :', o: ['tu relances', 'tu paies', 'tu te couches', 'tu fais tapis'], a: 1, why: 'Paye 91 % : face à une grosse mise, on contrôle la taille du pot.' },
      { q: 'Q♠Q♣ au bouton, flop 8♥ 7♥ 4♦, la grosse blinde checke :', o: ['check', 'un tiers du pot', '1,25 fois le pot', 'tapis'], a: 2, why: 'Mise gros 82 %, dont 57 % de surmise : beaucoup de tirages à faire payer.' },
      { q: 'Tu as volé de la petite blinde, la grosse blinde paie, flop K♦ 8♠ 3♣ :', o: ['tu mises toujours', 'tu checkes plus d’une fois sur deux', 'tu fais tapis', 'tu te couches'], a: 1, why: 'Hors de position, le solveur checke 54 % même sur ce flop.' }
    ]
  };

